// ===== eingebettet aus src/fehlerklassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const fehlerklassen = (() => {
const module = { exports: {} };
// Fehlerklassen und Statuscode-Mapping (Masterprompt 3, Bauplan 3).
// EPA-Fehler werden als Text "[EPA:<status>:<CODE>:<Vorgangs-ID|->] <Meldung>" geworfen,
// damit der Error-Handler (EPA-05) sie aus execution.error.message zurücklesen kann.

const FEHLERCODES = Object.freeze({
	UNGUELTIGES_FORMAT: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNGUELTIGER_AUSLOESER: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNBEKANNTER_STATUS: { status: 400, klasse: 'Eingabe', retrybar: false },
	AUTH_FEHLER: { status: 401, klasse: 'Authentifizierung', retrybar: false },
	KEINE_BERECHTIGUNG: { status: 403, klasse: 'Authentifizierung', retrybar: false },
	VORGANG_NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	KONFIG_NICHT_GEFUNDEN: { status: 404, klasse: 'Konfiguration', retrybar: false },
	NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	DUPLIKAT: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_STATUSWECHSEL: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_AUSLOESER: { status: 409, klasse: 'Konflikt', retrybar: false },
	VERSIONSKONFLIKT: { status: 409, klasse: 'Konflikt', retrybar: true },
	GESPERRT: { status: 409, klasse: 'Konflikt', retrybar: true },
	KONFIG_MEHRDEUTIG: { status: 409, klasse: 'Konfiguration', retrybar: false },
	FREIGABE_ABGELAUFEN: { status: 410, klasse: 'Freigabe', retrybar: false },
	EXTRAKTION_UNGUELTIG: { status: 422, klasse: 'LLM', retrybar: false },
	KONFIGURATIONSFEHLER: { status: 424, klasse: 'Konfiguration', retrybar: false },
	RATE_LIMIT: { status: 429, klasse: 'Upstream', retrybar: true },
	UPSTREAM_FEHLER: { status: 502, klasse: 'Upstream', retrybar: true },
	NICHT_ERREICHBAR: { status: 503, klasse: 'Upstream', retrybar: true },
	ZEITUEBERSCHREITUNG: { status: 504, klasse: 'Upstream', retrybar: true },
	UNBEKANNT: { status: 500, klasse: 'Unbekannt', retrybar: false },
});

// Bei diesen Codes bearbeitet eine andere Ausführung den Vorgang bzw. die Mail ist schon verarbeitet:
// der Vorgang wird NICHT auf "Eskaliert / Manuell" gesetzt (sonst würde ein Parallellauf gestört).
const OHNE_ESKALATION = Object.freeze(['VERSIONSKONFLIKT', 'GESPERRT', 'DUPLIKAT']);

// Fehler aus diesen Workflows werden gemeldet, aber nicht durch "Vorgang sichern" eskaliert: EPA-05 sichert Vorgänge
// selbst über "EPA SW Status setzen". Schlüge das fehl und würde erneut gesichert, entstünde eine Fehlerschleife.
const OHNE_SICHERUNG_AUS = Object.freeze(['EPA SW Status setzen']);

const EPA_MUSTER = /^\[EPA:(\d{3}):([A-Z_]+):([^\]]*)\]\s*([\s\S]*)$/;

function formatEpaFehler(code, vorgangsId, meldung) {
	const def = FEHLERCODES[code] || FEHLERCODES.UNBEKANNT;
	return `[EPA:${def.status}:${FEHLERCODES[code] ? code : 'UNBEKANNT'}:${vorgangsId || '-'}] ${meldung || ''}`.trim();
}

/** Wirft einen EPA-Fehler (für Code-Nodes). */
function epaFehler(code, vorgangsId, meldung) {
	const err = new Error(formatEpaFehler(code, vorgangsId, meldung));
	err.epaCode = code;
	return err;
}

function parseEpaFehler(text) {
	if (typeof text !== 'string') return null;
	// n8n stellt der Meldung manchmal Präfixe voran; das Muster darf irgendwo in der ersten Zeile beginnen.
	const start = text.indexOf('[EPA:');
	if (start < 0) return null;
	const m = text.slice(start).match(EPA_MUSTER);
	if (!m) return null;
	return {
		status: Number(m[1]),
		code: m[2],
		vorgangsId: m[3] === '-' ? null : m[3],
		meldung: m[4].trim(),
	};
}

/** Entfernt personenbezogene Daten und kürzt (keine Mail-Inhalte im Fehlerlog). */
function bereinigeMeldung(text, maxLaenge = 300) {
	if (text === undefined || text === null) return '';
	let s = String(text)
		.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '<email>')
		.replace(/\+?\d[\d\s/().-]{7,}\d/g, '<nummer>')
		.replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/g, 'Bearer <token>')
		.replace(/\s+/g, ' ')
		.trim();
	if (s.length > maxLaenge) s = s.slice(0, maxLaenge - 1) + '…';
	return s;
}

function codeAusHttpStatus(status) {
	const n = Number(status);
	if (!Number.isFinite(n)) return null;
	if (n === 400 || n === 422) return 'UNGUELTIGES_FORMAT';
	if (n === 401) return 'AUTH_FEHLER';
	if (n === 403) return 'KEINE_BERECHTIGUNG';
	if (n === 404) return 'NICHT_GEFUNDEN';
	if (n === 408 || n === 504) return 'ZEITUEBERSCHREITUNG';
	if (n === 409) return 'DUPLIKAT';
	if (n === 429) return 'RATE_LIMIT';
	if (n === 503) return 'NICHT_ERREICHBAR';
	if (n >= 500 && n < 600) return 'UPSTREAM_FEHLER';
	return null;
}

function codeAusText(text) {
	const t = String(text || '');
	if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|timeout of \d+ms/i.test(t)) return 'ZEITUEBERSCHREITUNG';
	if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|service unavailable/i.test(t)) return 'NICHT_ERREICHBAR';
	if (/rate.?limit|too many requests/i.test(t)) return 'RATE_LIMIT';
	if (/invalid_grant|unauthori[sz]ed|token (has )?expired|invalid.?token|authentication failed|password authentication/i.test(t)) return 'AUTH_FEHLER';
	if (/forbidden|insufficient privileges|access denied|permission denied/i.test(t)) return 'KEINE_BERECHTIGUNG';
	if (/duplicate key|unique constraint/i.test(t)) return 'DUPLIKAT';
	return null;
}

/**
 * Klassifiziert einen Fehler.
 * @param {{message?: string, description?: string, httpCode?: string|number}} fehler
 */
function klassifiziereFehler(fehler) {
	const f = fehler || {};
	const epa = parseEpaFehler(f.message) || parseEpaFehler(f.description);
	let code;
	let vorgangsId = null;
	let meldung;
	if (epa) {
		code = FEHLERCODES[epa.code] ? epa.code : 'UNBEKANNT';
		vorgangsId = epa.vorgangsId;
		meldung = epa.meldung;
	} else {
		code = codeAusHttpStatus(f.httpCode) || codeAusText(`${f.message || ''} ${f.description || ''}`) || 'UNBEKANNT';
		meldung = f.message || f.description || '';
	}
	const def = FEHLERCODES[code];
	return {
		statuscode: def.status,
		fehlercode: code,
		klasse: def.klasse,
		retrybar: def.retrybar,
		eskalieren: !OHNE_ESKALATION.includes(code),
		vorgangsId,
		meldung: bereinigeMeldung(meldung),
	};
}

/**
 * Baut aus der Ausgabe des Error Trigger einen Fehlerlog-Eintrag (ohne Mail-Inhalte).
 * Error Trigger liefert entweder {execution, workflow} oder bei Trigger-Fehlern {trigger, workflow}.
 */
function ausErrorTrigger(json) {
	const j = json || {};
	const exec = j.execution || {};
	const err = exec.error || (j.trigger && j.trigger.error) || {};
	const k = klassifiziereFehler({
		message: err.message,
		description: err.description,
		httpCode: err.httpCode,
	});
	const node = (err.node && err.node.name) || exec.lastNodeExecuted || null;
	const workflow = j.workflow || {};
	// Markierung " *" (fehlende Credentials) gehört nicht zum Namen
	const ausSicherung = OHNE_SICHERUNG_AUS.includes(String(workflow.name || '').replace(/\s*\*$/, ''));
	return {
		statuscode: k.statuscode,
		fehlercode: k.fehlercode,
		klasse: k.klasse,
		retrybar: k.retrybar,
		eskalieren: k.eskalieren && Boolean(k.vorgangsId) && !ausSicherung,
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
		execution_id: exec.id !== undefined && exec.id !== null ? String(exec.id) : null,
		execution_url: exec.url || null,
		modus: exec.mode || (j.trigger && j.trigger.mode) || null,
		vorgangs_id: k.vorgangsId,
		meldung: k.meldung,
	};
}

function escapeHtml(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function alarmHtml(eintrag) {
	const e = eintrag;
	const zeilen = [
		`<b>EPA-Fehler ${e.statuscode} ${escapeHtml(e.fehlercode)}</b> (${escapeHtml(e.klasse)})`,
		`Workflow: ${escapeHtml(e.workflow_name || e.workflow_id || '?')}`,
		`Node: ${escapeHtml(e.node || '?')}`,
		`Vorgang: ${escapeHtml(e.vorgangs_id || '–')}`,
		`Meldung: ${escapeHtml(e.meldung || '–')}`,
		e.retrybar ? 'Hinweis: vorübergehender Fehler, erneuter Versuch kann helfen.' : 'Hinweis: dauerhafter Fehler, bitte prüfen.',
	];
	if (e.execution_url) zeilen.push(`<a href="${escapeHtml(e.execution_url)}">Ausführung ${escapeHtml(e.execution_id)} öffnen</a>`);
	return zeilen.join('<br>');
}

module.exports = {
	FEHLERCODES,
	OHNE_ESKALATION,
	OHNE_SICHERUNG_AUS,
	formatEpaFehler,
	epaFehler,
	parseEpaFehler,
	bereinigeMeldung,
	klassifiziereFehler,
	ausErrorTrigger,
	alarmHtml,
	escapeHtml,
};
return module.exports;
})();
// ===== Ende src/fehlerklassen.js =====
// ===== eingebettet aus src/llmSchema.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const llmSchema = (() => {
const module = { exports: {} };
// LLM-Anbindung ohne Tools (Masterprompt A4, B2, 6): Ausgabeschemata, eigener Schema-Validator (n8n Cloud erlaubt
// im Code-Node keine externen Bibliotheken), Prompt-Aufbau mit klar abgegrenzten, nicht vertrauenswürdigen Mail-Daten,
// Auswertung der OpenAI-Antwort inkl. Retry-Entscheidung.

const AUFGABEN = ['klassifizierung', 'extraktion', 'entwurf'];
const KLASSEN = ['anfrage', 'keine_anfrage', 'unklar'];
const MAX_VERSUCHE_TECHNISCH = 3; // 429, 5xx, Timeout
const MAX_KORREKTUREN = 1; // ungültiges JSON/Schema

// ---------------------------------------------------------------- Schemata

function klassifizierungSchema(vorgangstypen) {
	const typen = [...(vorgangstypen || [])];
	return {
		type: 'object',
		additionalProperties: false,
		required: ['klasse', 'konfidenz', 'begruendung_kurz', 'vorgangstyp', 'sprache', 'verdacht_manipulation'],
		properties: {
			klasse: { type: 'string', enum: KLASSEN },
			konfidenz: { type: 'number', minimum: 0, maximum: 1 },
			begruendung_kurz: { type: 'string', maxLength: 300 },
			vorgangstyp: { type: ['string', 'null'], enum: [...typen, null] },
			sprache: { type: 'string', pattern: '^[a-z]{2}$' },
			verdacht_manipulation: { type: 'boolean' },
		},
	};
}

/** Extraktionsschema dynamisch aus der Feldliste der Config: je Feld { wert, quelle, konfidenz }. */
function extraktionSchema(felder) {
	const props = {};
	for (const f of felder || []) {
		props[f.feldname] = {
			type: 'object',
			additionalProperties: false,
			required: ['wert', 'quelle', 'konfidenz'],
			properties: {
				// Werte immer als Text: die Normalisierung (Zahl, Datum, PLZ) macht die Pflichtfeld-Prüfung deterministisch.
				wert: { type: ['string', 'null'], maxLength: 500 },
				quelle: { type: ['string', 'null'], maxLength: 200 },
				konfidenz: { type: 'number', minimum: 0, maximum: 1 },
			},
		};
	}
	return {
		type: 'object',
		additionalProperties: false,
		required: ['felder', 'verdacht_manipulation'],
		properties: {
			felder: { type: 'object', additionalProperties: false, required: Object.keys(props), properties: props },
			verdacht_manipulation: { type: 'boolean' },
		},
	};
}

/** Entwurf der Rückfrage: nur die Hülle. Bausteine, Signatur und KI-Hinweis setzt src/entwurf.js ein. */
function entwurfSchema() {
	const teil = (max) => ({ type: 'string', maxLength: max });
	return {
		type: 'object',
		additionalProperties: false,
		required: ['anrede', 'einleitung', 'schluss'],
		properties: { anrede: teil(80), einleitung: teil(400), schluss: teil(300) },
	};
}

function schemaFuer(aufgabe, kontext) {
	if (aufgabe === 'entwurf') return entwurfSchema();
	if (aufgabe === 'klassifizierung') return klassifizierungSchema(kontext.vorgangstypen);
	if (aufgabe === 'extraktion') return extraktionSchema(kontext.felder);
	throw new Error(`Unbekannte LLM-Aufgabe "${aufgabe}"`);
}

// ---------------------------------------------------------------- Validator (Teilmenge von JSON Schema)

function typVon(w) {
	if (w === null) return 'null';
	if (Array.isArray(w)) return 'array';
	if (typeof w === 'number') return Number.isInteger(w) ? 'integer' : 'number';
	return typeof w;
}

function passtTyp(w, typ) {
	const t = typVon(w);
	return t === typ || (typ === 'number' && t === 'integer');
}

/** Gibt eine Liste von Fehlern zurück (leer = gültig). */
function validieren(wert, schema, pfad = '$') {
	const fehler = [];
	const typen = Array.isArray(schema.type) ? schema.type : schema.type ? [schema.type] : [];
	if (typen.length && !typen.some((t) => passtTyp(wert, t))) {
		return [`${pfad}: erwartet ${typen.join('|')}, ist ${typVon(wert)}`];
	}
	if (schema.enum && !schema.enum.some((e) => e === wert)) fehler.push(`${pfad}: Wert ${JSON.stringify(wert)} nicht erlaubt`);
	if (typeof wert === 'number') {
		if (schema.minimum !== undefined && wert < schema.minimum) fehler.push(`${pfad}: kleiner als ${schema.minimum}`);
		if (schema.maximum !== undefined && wert > schema.maximum) fehler.push(`${pfad}: größer als ${schema.maximum}`);
	}
	if (typeof wert === 'string') {
		if (schema.maxLength !== undefined && wert.length > schema.maxLength) fehler.push(`${pfad}: länger als ${schema.maxLength} Zeichen`);
		if (schema.pattern && !new RegExp(schema.pattern).test(wert)) fehler.push(`${pfad}: Format ungültig`);
	}
	if (typVon(wert) === 'object') {
		const props = schema.properties || {};
		for (const r of schema.required || []) if (!(r in wert)) fehler.push(`${pfad}.${r}: fehlt`);
		for (const [k, v] of Object.entries(wert)) {
			if (props[k]) fehler.push(...validieren(v, props[k], `${pfad}.${k}`));
			else if (schema.additionalProperties === false) fehler.push(`${pfad}.${k}: nicht erlaubt`);
		}
	}
	if (Array.isArray(wert) && schema.items) wert.forEach((v, i) => fehler.push(...validieren(v, schema.items, `${pfad}[${i}]`)));
	return fehler;
}

/**
 * Schema für OpenAI Structured Outputs (strict). Nur Kern-Schlüsselwörter, deren Unterstützung sicher ist;
 * Längen, Zahlenbereiche und Muster prüft danach unser eigener Validator.
 */
function fuerOpenAi(schema) {
	const KERN = ['type', 'enum', 'properties', 'required', 'additionalProperties', 'items', 'description'];
	const out = {};
	for (const k of KERN) if (k in schema) out[k] = schema[k];
	if (out.properties) out.properties = Object.fromEntries(Object.entries(out.properties).map(([k, v]) => [k, fuerOpenAi(v)]));
	if (out.items) out.items = fuerOpenAi(out.items);
	return out;
}

/** JSON aus der Modellantwort lesen (toleriert ```json-Zäune). */
function jsonLesen(text) {
	if (typeof text !== 'string' || !text.trim()) return { ok: false, fehler: 'leere Antwort' };
	let s = text.trim();
	const zaun = s.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
	if (zaun) s = zaun[1];
	try {
		return { ok: true, wert: JSON.parse(s) };
	} catch (e) {
		return { ok: false, fehler: `kein gültiges JSON (${String(e.message).slice(0, 80)})` };
	}
}

// ---------------------------------------------------------------- Prompt-Aufbau

/** Mailinhalt als Datenblock. Abschluss-Tags im Inhalt werden entschärft, damit der Block nicht verlassen werden kann. */
function datenblock(name, inhalt) {
	const sicher = String(inhalt ?? '').replace(/<\s*\/?\s*(mail_daten|anhang_daten|bekannte_daten)\b/gi, (m) => m.replace('<', '[').replace(/\s/g, ''));
	return `<${name}>\n${sicher}\n</${name}>`;
}

/** Mail-Daten für den Prompt: nur, was für die Aufgabe nötig ist (keine Adressen außer der Domain). */
function mailText(mail, { mitAnhaengen = true, anhangZeichen = Infinity } = {}) {
	const z = [
		`Betreff: ${mail.betreff || '(leer)'}`,
		`Absender-Domain: ${mail.absender_domain || '(unbekannt)'}`,
		`Weiterleitung: ${mail.ist_weiterleitung ? 'ja' : 'nein'}`,
		'Text:',
		mail.text || '(kein Text)',
	];
	const anh = (mail.anhaenge || []);
	if (anh.length) {
		z.push('', 'Anhänge:');
		for (const a of anh) z.push(`- ${a.name} (${a.typ}, Status: ${a.status})`);
		if (mitAnhaengen) {
			for (const a of anh.filter((x) => x.text)) {
				const t = a.text.length > anhangZeichen ? a.text.slice(0, anhangZeichen) + '\n[… gekürzt]' : a.text;
				z.push('', `=== Inhalt Anhang "${a.name}" ===`, t);
			}
		}
	}
	return z.join('\n');
}

function feldliste(felder) {
	return (felder || []).map((f) => {
		const regel = f.validierungsregel && Object.keys(f.validierungsregel).length ? ` Regel: ${JSON.stringify(f.validierungsregel)}.` : '';
		return `- ${f.feldname} (${f.anzeigename}; Typ ${f.typ}; ${f.pflicht ? 'Pflicht' : 'optional'}): ${f.extraktions_hinweis || f.anzeigename}.${regel}`;
	}).join('\n');
}

function ersetzen(vorlage, variablen) {
	return String(vorlage || '').replace(/\{\{\s*([A-Z_]+)\s*\}\}/g, (m, k) => (k in variablen ? String(variablen[k]) : m));
}

/**
 * Baut den Request-Body für /v1/chat/completions.
 * @param {string} aufgabe klassifizierung | extraktion
 * @param {{system: string, user_vorlage: string, version: string}} prompt aus der Prompt-Registry
 * @param {object} kontext { mail, vorgangstypen?, felder?, hinweise?, heute? }
 * @param {{modell, temperatur, max_tokens}} profil
 */
function anfrageBauen(aufgabe, prompt, kontext, profil) {
	if (!AUFGABEN.includes(aufgabe)) throw new Error(`Unbekannte LLM-Aufgabe "${aufgabe}"`);
	const schema = schemaFuer(aufgabe, kontext);
	const mailBlock = aufgabe === 'entwurf'
		// Datenminimierung: für die Hülle reichen Name und Betreff, kein Mailinhalt.
		? datenblock('mail_daten', `Name des Kunden: ${kontext.name || '(unbekannt)'}\nBetreff: ${kontext.betreff || '(leer)'}`)
		: datenblock('mail_daten', mailText(kontext.mail, aufgabe === 'extraktion' ? {} : { anhangZeichen: 1000 }));
	const variablen = {
		MAIL: mailBlock,
		ANREDE_STIL: kontext.anrede_stil || 'Sie',
		SPRACHE: kontext.sprache || 'de',
		LUECKEN: (kontext.luecken || []).map((l) => `- ${l}`).join('\n') || '- keine',
		RUNDE: String(kontext.runde || 1),
		VORGANGSTYPEN: (kontext.vorgangstypen || []).join(', ') || '(keine)',
		FELDLISTE: feldliste(kontext.felder),
		HINWEISE: (kontext.hinweise || []).length ? kontext.hinweise.map((h) => `- ${h}`).join('\n') : '- keine',
		HEUTE: kontext.heute || '',
		SCHEMA: JSON.stringify(schema),
	};
	const userText = ersetzen(prompt.user_vorlage, variablen);
	const bilder = aufgabe === 'extraktion' ? ((kontext.mail && kontext.mail.anhaenge) || []).filter((a) => a.bild && a.bild_data_url) : [];
	const userInhalt = bilder.length
		? [{ type: 'text', text: userText }, ...bilder.map((b) => ({ type: 'image_url', image_url: { url: b.bild_data_url, detail: 'high' } }))]
		: userText;
	return {
		model: profil.modell,
		temperature: profil.temperatur,
		max_tokens: profil.max_tokens,
		messages: [
			{ role: 'system', content: ersetzen(prompt.system, variablen) },
			{ role: 'user', content: userInhalt },
		],
		response_format: { type: 'json_schema', json_schema: { name: aufgabe, strict: true, schema: fuerOpenAi(schema) } },
	};
}

// ---------------------------------------------------------------- Antwort auswerten

function wartezeitMs(headers, versuch) {
	const h = headers || {};
	const ra = h['retry-after'] ?? h['Retry-After'];
	const sek = Number(ra);
	if (Number.isFinite(sek) && sek >= 0) return Math.min(60000, Math.max(1000, sek * 1000));
	return Math.min(60000, 2000 * 2 ** (versuch - 1));
}

/**
 * Entscheidet nach einem HTTP-Aufruf, wie es weitergeht.
 * @param {object} antwort Ausgabe des HTTP-Request-Nodes (fullResponse) oder { error } bei Timeout/Netzwerkfehler
 * @param {object} zustand { body, schema, versuch, korrekturen }
 * @returns {{ aktion: 'fertig'|'wiederholen'|'korrigieren'|'ungueltig'|'fehler', ... }}
 */
function antwortAuswerten(antwort, zustand) {
	const a = antwort || {};
	const versuch = zustand.versuch || 1;
	const technisch = (code, text) => (versuch < MAX_VERSUCHE_TECHNISCH
		? { aktion: 'wiederholen', warte_ms: wartezeitMs(a.headers, versuch), grund: text, code }
		: { aktion: 'fehler', code, grund: `${text} (nach ${versuch} Versuchen)` });

	if (a.error || a.statusCode === undefined) {
