	}
	if (typVon(wert) === 'object') {
		const props = schema.properties || {};
		for (const r of schema.required || []) if (!(r in wert)) fehler.push(`${pfad}.${r}: fehlt`);
		for (const [k, v] of Object.entries(wert)) {
